function action(name: string, appliesTo: ActionDefinition['appliesTo']): ActionDefinition {
    return {
        agent: null,
        appliesTo,
        permissionMode: null,
        builtin: false,
        command: 'run',
        description: name,
        icon: null,
        id: `action-${name}`,
        label: name,
        model: null,
        needsWorkTree: false,
        on: [],
        onAfter: [],
        onBefore: [],
        onState: null,
        phrases: [],
        prompt: null,
        showCommandWindow: false,
        sourcePath: `actions/${name}.json`,
        thinkingLevel: null,
        trackFileChanges: false,
        streaming: false,
        type: 'command',
    }
}

function card(id: string, status: string | null): Card {
    return {
        agentConversationErrors: [],
        agentConversations: [],
        content: '',
        header: {
            affects: [], after: null, agentLogReferences: [], changedFiles: [], author: null, id, internalId: id.toLowerCase(), owner: null,
            policy: {}, references: [], status, title: id,
        },
        hasFrontmatter:true,
        isActive: true,
        path: `design/${id}.md`,
    }
}

